INSERT INTO `fish_letters` VALUES (1,17,43,'안녕 손범수! 나는 매부리바다거북이야. 바다에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:07:36.003580'),(2,6,70,'안녕 ㅁㄴㅇㄹ! 나는 넓적부리도요이야. 연안에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:20:51.680405'),(3,6,23,'안녕 ㅁㄴㅇㄹ! 나는 고리무늬물범이야. 연안에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:23:17.941362'),(4,6,27,'안녕 ㅁㄴㅇㄹ! 나는 바다쇠오리이야. 연안에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:24:20.062155'),(5,6,57,'안녕 ㅁㄴㅇㄹ! 나는 흰수염바다오리이야. 연안에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:24:54.356260'),(6,21,28,'안녕 류승찬! 나는 칠면초이야. 갯벌에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:32:38.656674'),(7,23,34,'안녕 권민짜이짜이! 나는 칠게이야. 갯벌에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',1,'2025-12-30T19:34:13.957801'),(8,21,18,'안녕 류승찬! 나는 분홍접시조개이야. 갯벌에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:36:53.522426'),(9,21,73,'안녕 류승찬! 나는 남방방게이야. 갯벌에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:40:34.517123'),(10,21,72,'안녕 류승찬! 나는 노랑부리백로이야. 갯벌에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',1,'2025-12-30T19:41:18.484248'),(11,21,54,'안녕 류승찬! 나는 청다리도요사촌이야. 갯벌에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',1,'2025-12-30T19:42:09.270102'),(12,11,50,'안녕 권민재! 나는 망둥어이야. 갯벌에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',1,'2025-12-30T19:42:34.893431'),(13,21,19,'안녕 류승찬! 나는 밤게이야. 갯벌에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:42:40.742412'),(14,11,75,'안녕 권민재! 나는 대추귀고둥이야. 하구역에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',1,'2025-12-30T19:44:27.559607'),(15,17,24,'안녕 손범수! 나는 범고래이야. 바다에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:46:59.737683'),(16,11,54,'안녕 권민재! 나는 청다리도요사촌이야. 갯벌에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T19:50:01.232346'),(17,21,4,'안녕 류승찬! 나는 붉은바다거북이야. 바다에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',1,'2025-12-30T20:00:00.117800'),(18,21,8,'안녕 류승찬! 나는 혹등고래이야. 바다에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T20:01:09.262447'),(19,21,24,'안녕 류승찬! 나는 범고래이야. 바다에 살고 있어. 나를 아쿠아리움에 넣어줘서 고마워!',0,'2025-12-30T20:06:58.728498');
