/*!40000 ALTER TABLE `species` DISABLE KEYS */;
INSERT INTO `species` VALUES (1,'갯게',1,100,'/static/images/sticker_갯게.png','등껍질의 세로 길이는 3cm, 가로 길이는 4cm 정도입니다. 등껍질의 양옆 가장자리가 볼록한 사각형이고 예리하지 않으며 전면에 짧은 털이 덮여 있습니다. 옆 가장자리는 매우 볼록하고 4개의 넓은 이빨모양의 돌기가 있는데 맨 뒤의 것은 구분이 뚜렷하지 않습니다. 집게다리는 크고 억세게 생겼는데 수컷의 집게다리는 암컷의 집게다리보다 훨씬 큽니다.\n\n연안 기수역의 도랑이나 습지에 구멍을 파고 사는데, 갯벌 윗 부분에 깊은 구멍을 파고 살기도 합니다.','하구역'),(2,'상괭이',2,100,'/static/images/sticker_상괭이.png','몸색깔은 대개 회갈색이며, 갓 태어났을 때는 흑색이나, 성장함에 따라 흑갈색으로 점차 변해 회백색이 되고, 다시 흑색으로 변해요. 다 자란 때의 몸길이는 최대 2m이며 수컷이 암컷보다 약간 크며 등지느러미가 없고 높이 1cm 정도의 튀어나오는 부분이 등의 흉부로부터 꼬리자루까지 있답니다. 가슴지느러미는 몸 길이의 약 1/6로 비교적 큰 편이며, 꼬리지느러미 너비는 비교적 커서 몸 길이의 1/4 정도에 달하며 아래위턱 좌우에 16～18개의 작은 이빨이 있어요.\n\n우리나라 연안에서 쉽게 관찰되며 번식기에는 다양한 색을 가진 개체들이 관찰됩니다. 수컷의 성숙은 4~6세, 암컷은 3~5세이고, 임신 기간은 10.1~11.5개월입니다. 수명은 최고 약 25년 정도로 추정되며 보통 2~3마리가 무리를 이루는데 연안에 멸치 무리가 형성되면 수십 마리가 무리를 이루는 경우가 목격되기도 합니다. 선박에 접근하지 않고 추적하면 신속히 도망가나, 큰돌고래 등 다른 종과 잘 어울리는 것으로 보이며 어류가 수면에 스치는 것으로 오인하는 경우가 많습니다. 어류, 오징어, 새우를 비롯한 갑각류 등 다양한 먹이를 먹어요. 각종 어구에 의해 함께 잡히는 문제가 있으며, 특히 서해에서 함께 잡히는 현상이 심각한 것으로 알려져 있으며 개체 수는 가파르게 감소중입니다.','바다'),(3,'실해송',1,100,'/static/images/sticker_실해송.png','몸통은 회초리 모양이며 줄기가 나누어지지 않고 불규칙하게 길게 뻗어있으며, 실해송 중에서 큰 것들은 끝부분에서 크게 굽어져서 완만하게 S자 모양을 이룹니다. 산호를 이루는 단단한 뼈대인 골축에는 1mm 정도마다 뚜렷한 마디가 있으며, 가시가 나있는데 12~14줄이 완만한 나선형을 이루며 세로로 배열되어 있습니다. 촉수가 나 있는 작은 돌기들인 폴립은 1cm 내에 6개 정도가 있고 불규칙적으로 모든 면에서 돋아나 있습니다. 중심 뼈대는 검은색 또는 진한 갈색이고 폴립은 흰색 또는 연한 노란색을 띈 모습입니다. 전체 길이는 보통 50~70cm 정도인데 1m를 넘는 실해송도 있습니다.\n\n남부지역에 국지적으로 흔한 여름철새로 번식하고, 낮에는 바다에서 살며, 해면 가까이에서는 다리는 늘어뜨리고 박쥐와 비슷하게 비행합니다. 번식지에서는 해가 지고 1시간 후에 돌아와 이른 새벽이면 섬을 떠나 대양으로 향합니다. 해양 환경 변화와 관련하여 학술적인 가치와 보전 가치가 높은 종이지만, 번식지에서 외래식물(쇠무릎)이 침입하여 바다제비가 집단으로 사망하는 등 개체 수가 줄어들 위험에 처해있습니다.','바닷속암반'),(4,'붉은바다거북',1,100,'/static/images/sticker_붉은바다거북.png','유난히 큰 머리로 인해 통나무 머리를 뜻하는 loggerhead 라고 붙렸으며 등갑은 하트 모양이며 길고 낮고 색깔은 주로 붉은색입니다. 등갑의 뒷 가장자리는 톱니모양이며 좌우 측면에 5쌍의 근갑판이 있고, 머리 위에 5개의 비늘이 있습니다. 발의 모양은 납작한 물갈퀴 모양이며 두 개의 발톱이 있습니다. 산란하는 암컷의 평균 등딱지 길이는 약 92cm, 무게는 113kg 정도로 큰 바다거북에 속한답니다.\n\n야생 개체군은 전반적으로 감소하는 추세이지만, 여전히 서식분포 범위가 넓습니다.','바다'),(5,'띠무늬물범',1,100,'/static/images/sticker_띠무늬물범.png','다 자란 암컷과 수컷은 몸 길이가 약 1.8m, 몸무게는 90~148 kg 정도 됩니다. 다른 물범보다 몸이 약간 가늘고 목, 앞다리, 어깨, 허리, 겨드랑이와 배에 두께가 불규칙한 백색의 넓은 띠가 둘러져 있습니다. 띠의 색은 털의 배경색보다 엷거나 회백색입니다. 갓 털갈이를 한 어른 수컷의 배경 털색은 적갈색 혹은 흑색입니다. 어른 암컷은 보다 옅은 황갈색 혹은 밝은 갈색이기 때문에 띠가 덜 선명하게 보입니다.\n\n주로 겨울에는 초여름 사이 빙하 부근에서 서식하고 먼바다에도 분포하는 것으로 알려져있습니다. 각 개체는 보통 독립적인 생활을 하며, 이른 4월부터 이른 5월 사이 빙하 위에서 출산합니다. 띠무늬물범은 얼음 위에서 빠르게 움질일 수 있으나, 그들의 서식지 특성상 쉽게 발견할 수 없습니다. 지역과 계절별 먹이가 다르며, 여러 종류의 물고기나 게를 먹이로 먹습니다.','연안'),(6,'긴가지해송',1,100,'/static/images/sticker_긴가지해송.png','몸통은 소나무모양이며 해송에 비해 가지가 더 풍성해보입니다. 줄기와 잔가지는 대부분 흰색을 띠지만, 갈색인 겨우도 있으며, 길이는 약 1m까지 자란답니다.\n\n수심 약 15~100m 범위에 서식하며,보통 20~30m 수심에서 주로 관찰됩니다. 경사진 암반에 단단하게 붙어삽니다. 우리나라 남해 외해 섬에서 서서히 개체수가 증가하고 있습니다.','바닷속암반'),(7,'복해마',1,100,'/static/images/sticker_복해마.png','몸길이는 약 17cm 정도로, 연홍색, 연한 갈색, 연한 검정색 등 다양한 몸색깔을 가집니다. 가슴지느러미와 뒷지느러미는 투명합니다.\n\n복해마는 주로 역대수역에 서식하며, 지구상에 서식하는 해마중 가장 많은 수를 가진 것으로 예상됩니다. 우리나라에서는 드물게 관찰됩니다.','바다숲'),(8,'혹등고래',2,100,'/static/images/sticker_혹등고래.png','몸길이는 출생 시 약 4.5m, 다 자란 경우 15m 정도이며, 체중은 30~40톤 정도입니다. 등지느러미가 혹 위에 있다 하여 혹등고래입니다. 전체적으로 검은색 혹은 암회색이며 목 부위와 배 쪽에 다양한 크기의 흰 색대(띠)가 있어요. 분기공 앞의 위턱은 편평하고 위에서 보면 넓고 둥그렇습니다. 위턱의 중앙을 따라 한 개의 융기선이 있습니다. 근육성 돌기열이 있으며 위턱과 아래턱에 혹들이 많아요. 가슴지느러미가 몸길이의 1/3에 이를 정도로 매우 길어요. 가슴지느러미는 아랫면이 희고 윗면의 가장자리도 부분적으로 흰색이며 가장자리가 울퉁불퉁합니다. 등지느러미는 몸길이에 비해 작고 몸통의 2/3 뒤쪽에 위치하고 낮은 삼각형의 뾰족한 갈고리 모양이며 잠수 시 등이 굽을 때 보인다. 아래턱에서 배꼽 혹은 그 뒤에까지 넓은 주름이 14~35개 있습니다. 꼬리지느러미 아래면의 무늬 모양으로 개체를 식별할 수 있습니다.\n\n최대 수명은 약 60년 정도이며, 임신기간은 11~12개월입니다. 2~3년에 한번 출산합니다. 보통 1~3마리가 이동하지만, 먹이 활동장이나 번식장에서는 큰 무리를 형성합니다. 수심이 얕은 연안에서 번식과 먹이활동을 하기 때문에 다른 종류에 비해 비교적 쉽게 발견됩니다. 대형고래 중 곡예가 가장 뛰어난 종으로 몸 전체를 수면 위로 멋지게 솟구쳐 오르기도 합니다. 기포막, 꼬리치기 등의 행동 특성을 보이며 협동으로 먹이를 모아 잡아먹는 기술도 가지고 있어요. 또한 고래류 중 가장 다양한 음의 소리를 내며 짝짓기 철이 되면 수컷은 복잡한 노래로 암컷을 유혹한답니다.','바다'),(9,'삼나무말',1,100,'/static/images/sticker_삼나무말.png','키가 약 40~50cm로 기다란 워닉둥의 형태를 지니는 갈조류입니다.\n\n차가운 물에서 생활하는 한대성 해조류이며, 조간대 아래쪽부터 수심 5m 지역에 서식합니다. 바위가 많은 곳에서는 쇠미역사촌과 야키시리구멍쇠미역과 함께 바다숲을 이루며 살아갑니다.','바다숲'),(10,'물개',1,100,'/static/images/sticker_물개.png','성숙한 수컷의 몸 길이는 2.1m, 체중은 270 kg, 암컷의 몸 길이는 1.5m, 체중은 50 kg 정도입니다. 털 길이가 짧고 균일한 바다사자나 큰바다사자와 달리 물개는 촘촘하고 가늘며 짧은 속 털 사이에 굵고 긴 겉털이 이중으로 나 있으며 수컷의 경우 육상으로 올라와 겉털이 마르면 수사자의 갈기처럼 크게 부풀어 보입니다. 체색은 흑갈색 또는 적갈색입니다. 암컷과 미성숙 개체들의 보호 털은 짧고 가늘며 체색은 짙은 은색과 회색의 중간색입니다.\n\n여름과 가을철 바위 지역 해변에서 서식하며 대부분의 시간을 바다에서 보내고, 6월 중순부터 8월까지가 번식기입니다. 일부다처제로 한 마리의 수컷이 최대 50마리 이상의 암컷을 거느린 번식 집단을 구성하여 번식합니다. 다소 깊은 수심에 사는 오징어나 어류를 먹이로 이용하며 최대 50m까지 잠수하기도 하며 주로 야간에 먹이활동을 하는 것으로 알려져 있습니다.','연안'),(11,'왕거머리말',1,100,'/static/images/sticker_왕거머리말.png','키가 50~90cm, 잎의 폭은 약 1cm, 잎맥의 수는 9~11개로 나타나며, 꽃이 피는 가지는 60~80cm 정도입니다. 땅속을 기는 0.5cm 지름의 땅속줄기는 마디 당 약 2cm 길이로 자라나며, 마디마다 다수의 뿌리가 자란답니다.\n\n물살의 흐름이 빠르지 않은 내만이나 조하대(수심9~15m)에 서식하며, 7~8월에 꽃이 핍니다.','바다숲'),(12,'대왕고래',2,100,'/static/images/sticker_대왕고래.png','몸길이는 출생 시 약 7m 정도, 다 자랐을 때는 약 25m 정도이며, 체중은 125톤 정도로 지구상에서 현존하는 가장 큰 동물이에요. 몸은 전반적으로 밝은 푸른색을 띠는 회색이며, 옅은 색의 점들이 산재해 있어서 수중에서는 청백색으로 밝게 보입니다. 지느러미는 매우 작고, 삼각형에 가까운 낫 모양이며, 가슴지느러미는 길고 얇으며 끝이 뾰족합니다. 아래턱에서 배꼽 사이에 55~68개의 주름이 있어요. 등 지느러미는 매우 작고 삼각형에 가까운 낫모양입니다.\n\n임신기간은 약 11개월이며, 2~3년에 한 번 출산하며, 수명은 최대 약 100년 이상인 것으로 알려져 있어요. 일반적으로 단독으로 다니거나, 두 마리씩 짝을 이루어 다니기도 하지만, 먹이를 먹기위해서는 흩어져 있던 무리들이 모이기도 합니다. 짧게 잠수하는 것으로 알려져 있지만, 30분 이상 잠수하기도 합니다. 먹이로는 소형 갑각류인 난바다곤쟁이류를 먹어요.','바다'),(13,'망해송',1,100,'/static/images/sticker_망해송.png','몸통은 둥근 부채 모양으로 되어있으며, 무수히 많은 가지와 잔가지들이 빽빽하게 뻗어 부채 모양의 그물망을 이룹니다. 처음 나누어지는 가지는 약 40~60°의 각을 이루며 뻗어 나가고, 가장 작은 5번째 가지의 길이는 약 3mm의 크기를 보입니다. 가지들이 이루는 망의 간격은 약 3~5mm 정도입니다. 줄기와 잔가지 모두 밝은 갈색을 띱니다. 키는 약 40cm 정도이고 키보다 옆으로 더 넓은 모양을 나타냅니다.\n\n일본에서는 바닷 속 수심 40~100m 범위에 살고있는 것으로 알려졌었는데, 다른 곳에서는 보통 수심 약 20~40m 범위에서 관찰됩니다. 완만한 경사를 가진 바위에 단단히 부착하여 살고있습니다. 우리나라에서는 제주 문섬 주변에서만 발견되며 보기 드문 희귀종입니다.','바닷속암반'),(14,'포기거머리말',1,100,'/static/images/sticker_포기거머리말.png','땅속줄기의 길이가 짧아 덩어리로 자라는 것처럼 보이며, 키가 50~170cm, 잎의 쪽은 0.5~1cm, 잎맥의 수는 5~7개로 나타납니다. 꽃이 피는 가지는 50~170cm의 키를 가집니다.\n\n암수한몸의 다년생 여러해살이풀로, 물살이 비교적 느린 만의 조하대(수심 3~8m)의 모래바닥에 주로 분포하며, 거머리말과는 달리 포기거머리말은 물이 빠져나가고 난 후인 간조시에도 물 밖으로 노출되지 않습니다. 3월에 꽃이 피기 시작하고, 5~6월에 씨가 성숙합니다.','바다숲'),(15,'눈콩게',1,100,'/static/images/sticker_눈콩게.png','눈자루가 짧은 편이고 눈알이 원형에 가까우며 눈구멍은 있으나 깊지 않고 뒤로 젖혀져 위에서 보면 ‘八’자형의 모양을 보입니다. 밝은 베이지색의 반구형 등갑을 지녔다. 걷는 다리에는 전반적으로 연한 흑회색의 가로띠가 반복적으로 나타납니다. 집게발은 좌우대칭이며 수컷의 집게발이 암컷에 비해서 큽니다. 특히 집게발의 손등이 높아 전체적으로 삼각형을 이루어 손이 커 보입니다. 이 종에 있어서 동정키로 사용되는 것은 집게발의 긴마디에 있는 타원형의 고막(鼓膜)으로 크고 작은 두 개의 고막이 있습니다.\n\n조간대 중부에 서식하며, 서식지가 모래갯벌인 관계로 해사채취로 인한 서식지 파괴가 진행되고 있어 서식지 위협이 심각하다. 밀도가 높은 지역에서는 수컷 간의 다툼이 자주 일어나는 것을 볼 수 있습니다. 집게발로 상대를 “툭툭”치거나 배를 맞대고 몸을 “부르르” 떨면서 상대를 밀어내려는 행동을 자주 하며, 집게발을 좌우로 벌린 상태에서 상대를 위협하는 행동을 보입니다. 하지만 집게발의 힘이 약하고 특별한 방어능력이 없어 이런 행동을 하다가 곧바로 구멍 속으로 몸을 숨기는 행동을 보입니다.','하구역'),(16,'바다사자',1,100,'/static/images/sticker_바다사자.png','수컷의 몸 길이는 2.3~2.5m, 체중은 440~563kg, 암컷의 몸 길이는 1.5~1.8m, 체중은 50~110kg 정도로 성숙한 수컷은 암컷에 비해 매우 강하고 큽니다. 물개와 비슷하게 생겼으나, 수컷은 성숙하면 정수리에 볏 모양의 것이 돌출하며, 암컷의 정수리 부위에는 돌출 부위가 없습니다.\n\n주로 연안지역에서 생활하지만 강 하구나 먼바다에서도 발견됩니다. 연중 무리를 지어 생활하며, 일부다처제로 한 무리에는 새끼와 함께 20여 마리의 암컷이 포함되며, 최대 30년까지 생존한 기록이 있습니다. 오징어류, 문어류와 같은 두족류와 다양한 종류의 어류를 섭취하며, 계절적인 이동은 잘 알려져 있지 않습니다. 천적은 범고래와 상어로 알려져 있습니다.','연안'),(17,'밤수지맨드라미',1,100,'/static/images/sticker_밤수지맨드라미.png','몸통은 촉수 덩어리 부분에서 주황색, 촉수는 붉은색을 띱니다. 몸톹의 크기는 높이 약 30cm이며, 만개했을 때 보통 폭이 길이보다 좁습니다.\n\n수심 5~25m 사이에 서식하며, 해류의 흐름이 원활한 곳에서 큰수지맨드라미와함께 연산호 군락을 형성하며, 몸안에 산호숨이부채게와 줄새우 등 다양한 생물들이 공생합니다.','바닷속암반'),(18,'분홍접시조개',1,100,'/static/images/sticker_분홍접시조개.png','2.5cm 전후의 소형 조개류이며, 백색을 띱니다. 껍데기가 매우 얇아서 쉽게 부서집니다.\n\n수심 10m 전후의 고운 모래 바닥에서 흔히 발견됩니다. 가늘고 긴 수관을 이용하여 바닥에 쌓인 퇴적물에 포함된 유기물이나 미생물을 걸러 먹습니다.','갯벌'),(19,'밤게',1,100,'/static/images/sticker_밤게.png','전체적으로 동그란 형태이고, 주로 연녹색의 몸에 베이지색의 불규칙한 줄무늬가 있습니다. 눈자루가 없어서 눈알이 눈구멍에 밀착되어 있습니다.\n\n갯벌에서 죽은 물고기나 조개, 살아있는 민챙이나 갯지렁이 등을 먹이로 삼습니다. 서식 굴 없이 여기저기 돌아다니는 습성이 있습니다. 위험을 느끼거나 한낮의 뜨거운 햇빛을 피하기 위해 몸을 뒤로 움직여 갯벌을 파고 들어가는 습성이 있습니다.','갯벌'),(20,'새우말',1,100,'/static/images/sticker_새우말.png','키는 약 20~100cm, 잎의 폭은 약 0.3cm이며, 잎맥의 수는 잎의 아랫부분에서는 5개, 잎의 끝부분에서는 3개입니다. 땅속줄기는 약 0.5cm의 지름이며, 0.5cm 마다 마디를 형성하고, 마디마다 한 쌍의 뿌리와 검붉은색 섬유질 털을 가지고 있습니다.\n\n암수판몸에 여러해를 사는 해초류로, 주로 개방된 해안의 바위에 서식합니다. 주로 조간대부터 수심 3m 지역에 서식하지만, 수심 8m의 깊은곳에서 발견되기도 합니다. 3~6월 사이에 암꽃 가지와 수꽃 가지가 나타나며, 8~10월에 성숙한 종자(씨)가 생깁니다.','바다숲'),(21,'붉은발말똥게',1,100,'/static/images/sticker_붉은발말똥게.png','등껍질은 사각형이며 전체적으로 볼록하고 중앙은 아주 약간 오목합니다. 각 구역을 표현하는 홈이 뚜렷하고, 집게다리 바깥 면에 크고 작은 과립이 촘촘히 나 있으며, 안쪽 면에는 큰 과립이 있습니다. 손은 빨간색입니다.\n\n해안가나 하구역 습지, 심지어 주변의 숲속에서 발견되기도 합니다. 우리나라 일본, 타이완 등지에 서식하며, 무안, 대천에서 오래전에 발견되었습니다.','하구역'),(22,'의염통성게',1,100,'/static/images/sticker_의염통성게.png','몸길이는 6cm, 폭 5cm 정도이고, 위에서 보면 타원형에 가까우나 상대적으로 뒤쪽이 좁습니다. 가시는 대체로 거칠게 나타납니다.\n\n우리나라에서는 매우 희귀한 종으로, 조하대에서 수심 200m까지 서식하는 것으로 알려져 있습니다.','바닷속암반'),(23,'고리무늬물범',1,100,'/static/images/sticker_고리무늬물범.png','성숙한 암수 모두 최대 체장이 1.7m, 체중은 50~110 kg입니다. 점박이물범, 잔점박이물범과 닮았으나 겨드랑이몸통둘레가 체장의 80%에 달할 정도로 몸통이 큽니다. 머리는 작고 다소 둥글며 목은 아주 짧고 두껍습니다. 짙은색의 등과 옆면에는 엷은 색의 고리 무늬가 불규칙하게 흩어져 있습니다. 고리 무늬는 밝은 회색과 회색이 도는 흰색이며, 암수 모두 개체별 혹은 지역별 변이가 있기도 합니다. 배면에는 반점이 없거나 매우 드물게 있기 때문에 점박이물범, 잔점박이물범과 구분할 수 있는 특징이 됩니다. 바탕색은 변이가 있지만 보통 등 쪽은 약간짙은 회색이고 배 쪽은 엷은 은회색입니다.\n\n주로 3~4월에 유빙위에서 번식을 하고, 임신기간은 10~11개월이며, 일부일처제입니다. 물 밖에서는 매우조심스럽고 곰이나 사람 등 포식자의 존재를 정기적으로 살핍니다. 바다의 표층, 중층, 저층에 서식하는 다양한종류의 어류와 부유성 갑각류를 먹이로 하며, 홀로 혹은 작은 무리를 이루어 먹이를 찾습니다.','연안'),(24,'범고래',1,100,'/static/images/sticker_범고래.png','몸 전체가 짙은 흑색인데 눈의 위 뒷부분에는 흰색의 긴 타원형 반점이 있으며 복부는 흰색입니다. 등지느러미 뒤쪽에는 말안장 모양의 회색 대가 있습니다. 광택 있는 흑백의 몸 색깔과 높고 넓은 모양의 바로 선 등지느러미와 몸높이가 높아 다른 고래와 구별됩니다. 부리는 매우 짧고 불명료하며 주둥이는 원추형이며 둥근 이마와 부리 사이는 경사가 큽니다. 아래위턱의 좌우에 각각 전방으로 약간 기울어진 10～12개의 이빨이 있으며, 최대로 성장할 경우 암컷은 몸길이 최대 8.5m에 무게 7.5톤, 수컷의 경우 9.8m에 무게 10톤까지 자라게 됩니다.\n\n사회성이 가장 발달해 있는 것으로 알려져 있으며 1~50두가 군을 이룹니다. 오징어류 및 어류를 주식으로 하며 물개류 뿐만 아니라 대왕고래 등 대형 고래류를 집단으로 공격하여 포식하기도 하며, 수명은 약 50년이나 최대 100년까지도 생존하는 것으로 알려져 있습니다.','바다'),(25,'연수지맨드라미',1,100,'/static/images/sticker_연수지맨드라미.png','몸통은 활짝 폈을 때 나무 모양이며, 수축하면 브로콜리 모양으로 덩어리집니다. 기둥은 굵고 짧으며 보통 2개로 갈라지는데 가지는 둥근 기둥 모양으로 위로 갈수록 가늘어집니다.가는 가지 끝에는 10~12개의 촉수 덩어리가 배열되어 있습니다.몸통은 전체적으로 주황색이고 가지는 연노랑색입니다. 몸통의 크기는 활짝 폈을 때 높이 10cm, 폭 8~10cm 정도입니다.\n\n해류의 흐름이 원활한 수심 5~20m에 주로 서식하며, 군락을 형성할 만큼 개체군의 크기가 크지 않고, 대부분 단독으로 발견된답니다.','바닷속암반'),(26,'향고래',1,100,'/static/images/sticker_향고래.png','출생 시 몸 길이는 약 4m, 체중은 1톤 정도이며, 다 자란 수컷이 약 15m, 체중은 57톤, 암컷이 약 11m, 43.5톤 정도로 수컷과 암컷의 차이가 큽니다. 이빨 고래류 중에서 가장 큰 종이며, 몸체는 흑색 또는 회갈색입니다. 부리는 없고 머리는 몸 길이의 1/4~1/3에 이를 정도로 큰 것이 가장 큰 특징입니다. 머리와 등지느러미 사이의 몸체는 사각형이며 그 후방은 가늘어집니다. 피부는 쭈글쭈글하며, 연령이 많아질수록 머리부가 먼저 희게 됩니다. 등지느러미는 명확하지 않고 몸체의 2/3 정도 되는 위치에 피부가 삼각형 모양으로 솟아올라 있고, 그 뒤로 여러 개의 튀어나오는 부분인 연속되어 있습니다. 가슴지느러미는 몸체에 비해 크지 않습니다.\n\n임신기간은 15~16개월이며, 3~5년에 한번 출산하며, 수명은 약 70년 정도로 알려져 있습니다. 모계사회를 이루고, 20~40마리의 미성숙 육아 집단이 있으며, 성숙한 수컷은 육아 집단을 떠나 단독 혹은 수 마리가 무리를 이루어 다니면서 암컷을 찾는 전략을 취하고 있습니다. 약 2시간 동안 최대 3,200m까지 잠수하는 것으로 알려져 있으며, 저주파, 스테레오 형 클릭음이 개체마다 다르기 때문에 개체식별에 사용됩니다. 오징어나 문어류 등 두족류가 가장 선호하는 먹이로 알려져 있고, 10m가 넘는 대형 오징어를 포식하기도 합니다.','바다'),(27,'바다쇠오리',1,100,'/static/images/sticker_바다쇠오리.png','우리나라에서는 텃새로 섬에서 번식하는 것이 많다. 몸길이 약 25cm입니다. 암수 같은 빛깔입니다. 머리 위와 목덜미는 검은색이며, 멱과 가슴, 몸 아랫면은 흰색입니다.\n\n어구에 의해 함께 잡히는 피해가 심각하며 해양의 기름오염에도 큰 피해를 입고 있습니다. 기후변화, 수온상승에 따른 어종의 변화에 민감한 것으로 추정되어, 해양환경 모니터링의 지표종으로 활용성이 높습니다.','연안'),(28,'칠면초',1,100,'/static/images/sticker_칠면초.png','줄기는 높이 10~50cm 정도로 곧게 자라며 주로 붉은색을 띱니다. 꽃받침은 5갈래로 깊게 갈라지고, 수술 5개와 암술대 2개가 있습니다.\n\n서해안 중남부 해안가에서 자라는 1년생 초본으로 크게 무리 지어 자랍니다.','갯벌'),(29,'뿔쇠오리',1,100,'/static/images/sticker_뿔쇠오리.png','몸길이는 약 24cm, 체중은 183g 정도이며, 머리에 짧은 뿔깃이 있습니다. 부리는 길고 회갈색입니다. 머리는 검은색 바탕에 머리 꼭대기에서 뒷목까지 뚜렷한 흰색 줄이 있습니다. 등, 어깨깃, 허리, 윗꼬리덮깃은 어두운 회색입니다. 아래 목 부위, 가슴, 배, 아래꼬리덮깃은 흰색이며, 옆구리는 검은색으로 군데군데 회색빛을 띱니다. 아래날개덮깃은 흰색이고, 겨드랑이깃도 흰색으로 바깥쪽은 다소 검은색을 띱니다.\n\n일생의 대부분을 바다 위에서 사는 대표적인 해양성 조류입니다. 청어목 어류나 새우같은 것을 먹이로 삼습니다.  극히 적은 수의 번식지에서만 번식하며, 외래종의 침입에 큰 피해를 받을 수 있습니다.','연안'),(30,'검붉은수지맨드라미',1,100,'/static/images/sticker_검붉은수지맨드라미.png','몸통은 활짝 폈을 때 나무 모양이며, 수축하면 브로콜리 모양으로 덩어리집니다. 기둥은 굵고 둥글며 두 갈래로 갈라지고, 갈라진 가지에서 가는 가지를 치며 여기에 10~12개의 촉수가 배열됩니다. 촉수는 어두운 붉은색이고, 가는 가지는 연한 주황빛을 띠며 가지와 줄기는 깨끗한 하얀색입니다. 몸통의 크기는 다양한데 보통 활짝 폈을 때 높이 15cm, 폭 8~10cm 정도입니다.\n\n수심 10~30m에 주로 서식하며, 번식은 암수 생식세포가 결합하는 유성생식과 촉수를 떨어뜨리는 무성생식의 두 가지 방법 모두 이용하며, 시기는 8~9월로 알려져 있습니다. 서식환경은 수온 20~25도, 염도 30~35범위입니다.','바닷속암반'),(31,'자색수지맨드라미',1,100,'/static/images/sticker_자색수지맨드라미.png','몸체는 활짝 폈을 때 나무 모양이며, 수축하면 덩어리집니다. 기둥은 굵고 둥글며 10~13개의 촉수로 이루어진 덩어리가 가는 가지 끝에 있습니다.촉수는 어두운 붉은색이고 가는 가지들은 연한 노란색이며,가지와 줄기는 하얀색입니다. 몸통의 크기는 개체별로 다양한데 보통 활짝 폈을 때 높이 약 20cm이며, 폭은 이보다 약간 좁게 나타납니다.\n\n수심 20~50m 범위에 주로 서식하며, 번식은 암수 생식세포가 결합하는 유성생식과 촉수를 떨어뜨리는 무성생식의 두 가지 방법 모두 이용한답니다.','바닷속암반'),(32,'달랑게',1,100,'/static/images/sticker_달랑게.png','몸 가로길이 약 28.4mm, 세로길이 약 23.8mm정도이며 눈알이 크고 눈자루가 짧습니다. 등껍질은 전체적으로 사각형이며, 가운데가 볼록하여 통통한 느낌의 사각형입니다. 황갈색의 등은 점이나 무늬가 없어 매끄럽습니다.\n\n일조량에 따라 색깔이 변화합니다. 눈알이 크고 달리기를 잘하는 탓에 밤에 소리 없이 움직인다고 해서 영어권에서는 유령게(Ghost crab) 라고 불립니다. 모래해변을 대표하는 종으로 서남해안 및 도서지역의 모래해변이 발달하고 깨끗한 해변에 서식합니다. 야행성으로 밤에 서식 굴에서 나와 작은 집게발을 이용해 모래 표면을 긁어 입속에 넣고 먹이활동을 합니다. 모래 속 유기물을 섭취하고 순수한 모래는 입 밖으로 흘리게 되는데 이렇게 떨어진 모래는 럭비공 모양입니다. 이 종은 집게발의 손바닥에 대각선으로 돌기줄이 있어 문질러 소리를 내는데 이 소리로 서로 간의 의사소통을 하는 것으로 알려져 있습니다.','갯벌'),(33,'깃산호',1,100,'/static/images/sticker_깃산호.png','몸통은 새의 깃털과 유사하며, 가지 길이는 보통 5~10cm 내외로 살구색을 띠며 높이는 10~25cm입니다.\n\n해류의 소통이 원활한 암반에 부착하여 서식합니다.','바닷속암반'),(34,'칠게',1,100,'/static/images/sticker_칠게.png','크기는 약 40mm 정도이며, 몸통은 앞이 약간 더 넓은 사다리꼴 모양입니다. 수컷의 집게다리는 크며, 손바닥은 길고, 두 손가락은 안쪽으로 휘어있습니다. 암컷의 손바닥은 짧고, 발가락 마디의 앞부분은 숟가락 모양으로 파져있습니다.\n\n조간대(주로 내만)의 진흙 질 바닥에 타원형 구멍을 파고 살고 있습니다. 시각이 매우 예민하여 사람이 지나가면 약 20m 밖에서도 재빨리 구멍으로 들어가 버립니다. 낮에는 별로 활동하지 않고, 밤에 나와 활동합니다.','갯벌'),(35,'흰발농게',1,100,'/static/images/sticker_흰발농게.png','몸 크기는 약 18mm정도이며, 눈알이 크고, 수컷과 암컷의 집게다리 크기가 서로 다릅니다. 수컷의 경우 한쪽 집게발이 자신의 몸보다 크게 자라며, 한쪽 집게발은 아주 작아 먹이활동에만 사용합니다. 암컷의 경우 양쪽 집게발 모두 작아, 두발을 사용하여 먹이 활동을 합니다. 큰 집게발의 손등은 베이지색을 보이지만, 전체적으로는 흰색이어서 흰발농게라는 이름이 되었습니다.\n\n6월에 짝짓기가 시작되며 이 시기가 되면 수컷은 흰색 큰 집게발을 하늘 높이 올렸다 내렸다 하는 행동을 수시로 반복하며 주변의 암컷에게 구애행동을 합니다. 또한 영역을 확보하기 위한 수컷들의 집게발 싸움도 치열하게 발생합니다. 수컷이 집게발을 들어 올릴 때는 구애행동이나 영역 표시를 위한 행동인데 구애행동의 경우 몸을 좌우로 움직이며 집게발을 올렸다 내렸다 반복하는 반면 영역 표시나 혹은 상대에게 위협을 가하기 위해서 하는 행동은 몸을 움직이지 않고 그 자리에서 집게발만 상하로 올렸다 내렸다 하는 행동을 합니다.','갯벌'),(36,'측맵시산호',1,100,'/static/images/sticker_측맵시산호.png','몸통은 부채모양으로, 진한 붉은색이며, 촉수도 붉은색을 띱니다. 몸통의 높이는 약 20cm정도이며, 폭은 이보다 좁습니다.\n\n해수의 흐름이 원활한 수심 20m 내외의 부착하여 생활하고, 집단을 이루지 않고 독립적으로 서식합니다. 가지에는 태형동물, 환형동물 등이 부착하는 경우도 있답니다. 번식시기는 11월경이며, 성장속도가 느리답니다.','바닷속암반'),(37,'흑범고래',1,100,'/static/images/sticker_흑범고래.png','범고래와 비슷하나 전신이 흑색이며 몸체는 가늘고 깁니다. 가슴지느러미 사이의 복부는 약간 밝은 흑색이고, 머리는 작고 이마가 둥글며 뾰족합니다. 부리는 완전히 없고 입은 후방으로 치켜 올라가 있으며, 위턱이 아래턱보다 깁니다. 좌우 측에 흑색 반점이 있는 개체들이 있으며 아래위턱 좌우에 각각 8～11개의 날카로운 이빨을 가지고 있습니다. 등지느러미는 넓은 낫 모양으로 끝부분은 가늘고 약간 아래로 쳐져 있는 것이 특징이며, 몸길이는 약 3.9～6.0m, 무게는 약 2톤가량으로 수컷이 암컷보다 다소 큽니다.\n\n7년에 1회 계절에 관계없이 출산하며 수명은 수컷은 최대 56년, 암컷은 62년 정도로 알려져 있습니다. 어류와 오징어를 주 먹이로 하며 소형 고래류와 대형 고래류를 공격하기도 합니다.','바다'),(38,'유착나무돌산호',1,100,'/static/images/sticker_유착나무돌산호.png','몸통은 돌처럼 단단하며 나무 모양으로 불규칙하게 가지를 뻗습니다.가지는 굵고 원통형이며 서로 유착하여 덤불과 같이 자랍니다. 가지와 촉수는 대부분 선명한 주황색을 띠지만 진한 노란색이 나타나기도 합니다. 크기는 독립 개체의 경우 높이와 폭이 20cm 내외이지만, 덩어리를 이루는 경우에는 폭이 30~50cm(또는 3m 이상)으로 다양하답니다.\n\n우리나라에서는 수심 15~25m 사이에서 주로 발견되며, 특히 독도에 서식하는 개체군은 크게 집단을 형성하여 서식하며 작은 어류의 은신처 역할을 한답니다.','바닷속암반'),(39,'올리브바다거북',1,100,'/static/images/sticker_올리브바다거북.png','등갑은 전반적으로 둥글지만 앞뒤 길이가 양옆 길이에 비해 깁니다. 등 위쪽은 납작하며 전체적인 몸 색깔이 올리브색을 띠며 복부는 연한 노란색을 띱니다.\n\n자신이 태어난 모래사장에서 번식하고 어린 개체는 부화한 뒤 성적으로 성숙할 때까지 대양을 떠돌며 서식합니다. 번식 후에는 일반적으로 20℃ 이상의 해역에서 머무릅니다.','바다'),(40,'가시닻해삼',1,100,'/static/images/sticker_가시닻해삼.png','몸통길이는 약 10cm 전후로 퇴적물의 유기물을 먹는 해삼류입니다. 몸통에는 돌기가 없고 매끈하며, 상태에 따라 몸길이에 많은 차이가 있습니다. 전체적으로 옅은 분홍색을 띄며, 세로방향으로 5줄의 띠가 있습니다.\n\n진흙 또는 진흙모래 갯벌부터 수심10m 전후의 진흙 또는 진흙모래 바닥에서 흔히 발견됩니다. 바닥에서 5~10cm 깊이로 파고든 상태로 이동하며 퇴적물내 유기물을 먹습니다.','바닷속암반'),(41,'보리고래',1,100,'/static/images/sticker_보리고래.png','몸 길이는 출생 시 약 4.5m, 다 자랐을 때 약 12m 정도이며, 체중은 약 30톤 정도입니다. 등은 흑색이며 옆과 배쪽 후방이 흑색 혹은 회흑색입니다. 분기공 앞 주둥이 중앙에 융기선이 1개 있습니다. 등지느러미는 대형으로 몸 길이(몸길이)에 대한 등지느러미의 비율이 높은 편이고, 참고래에 비해 수직에 가깝다. 목주름은 가슴과 배꼽 사이의 중간에서 끝납니다.\n\n임신 기간은 10.5개월이며, 2~3년에 한번 저위도 해역에서 출산하며, 수명은 최대 약 70년 정도입니다. 울산연안에서 보리를 수확할 때 나타난다 하여 보리고래라 불렀다 합니다. 보통 2~3마리가 무리 지어 회유하고 수십 마리의 군(집단)을 형성하기도 합니다. 유영 속도는 수염고래류 중 가장 빠르며, 동물플랑크톤(주로 칼라누스 등의 요각류)이나 무리를 짓는 물고기들을 먹이로 먹습니다.','바다'),(42,'귀신고래',1,100,'/static/images/sticker_귀신고래.png','몸 길이는 출생 시 약 4.5m, 다 자랐을 때 16m 정도이며, 체중은 약 35톤 정도입니다. 몸 전체는 회색, 암회색을 띠며, 흰색의 상처 모양이 있습니다. 몸 표피(피부)에는 따개비, 굴 껍데기 등이 부착되어 있습니다. 등지느러미는 뚜렷하지 않고 여러 개의 작은 융기가 꼬리지느러미까지 연결되어 있으며, 다른 수염고래류의 특징인 복부 주름이 없고, 길이 1~2m 정도인 2~5개의 깊은 홈이 아래턱에 있습니다.\n\n임신기간은 13.5개월이며, 2~3년에 한번 출산하며 최대 수명은 약 70세 정도입니다. 다양한 저서 갑각류를 먹이로 취하며, 회유(이동) 시에는 주로 3마리 이하가 연안으로부터 수 km 이내를 통과합니다. 수면에 몸체 비상하기, 수직으로 세우기 등 곡예에 능합니다.','바다'),(43,'매부리바다거북',2,100,'/static/images/sticker_매부리바다거북.png','위턱의 앞끝이 매의 부리처럼 뾰족하기 때문에 매부리바다거북이란 이름이 붙여졌습니다. 머리 위에 2쌍의 비늘이 있으며 비교적 좁고, 양측이 평행합니다.등껍질의 뒷부분은 톱니 모양으로 뾰족합니다. 몸색깔은 매우 다양하며 광택의 줄무늬가 있고, 배는 맑은 황색입니다. 바다거북 중 가장 색깔이 화려한 종이며 칼라 패턴이 선풍기 모양으로 배열되어 있답니다. 배 쪽에는 2개의 융기가 있으며, 등껍질 길이는 최고 90cm에 달하는 중간 크기의 바다거북입니다.\n\n산란개체수는 약 8,000마리 정도로 추정되며, 개체군은 열대해역에 넓게 분포하지만 서식밀도는 거의 전 범위에서 낮고 몇 지역에서 적절한 서식밀도를 가집니다. 대부분 개체군은 심각하게 감소된 것으로 추정됩니다.','바다'),(44,'게바다말',1,100,'/static/images/sticker_게바다말.png','키는 약 20~100cm, 잎의 폭은 약 0.3cm이며, 잎맥의 수는 3개입니다. 땅속줄기는 약 0.4cm의 지름이며, 0.5cm 마다 마디를 형성하고, 마디마다 한 쌍의 뿌리와 검은색 섬유질 털을 가지고 있습니다.\n\n암수딴몸에 여러해를 사는 해초류로, 주로 개방된 해안의 바위에 서식합니다. 주로 조간대부터 수심 3m 지역에 서식하지만, 수심 12m의 깊은곳에서 발견되기도 합니다. 2~4월 사이에 암꽃 가지와 수꽃 가지가 나타나며, 6~7월에 암꽃 가지에서 10~12개의 성숙한 종자(씨)가 생깁니다.','바다숲'),(45,'브라이드고래',1,100,'/static/images/sticker_브라이드고래.png','몸길이는 출생 시 약 4m, 다 자랐을 경우 약 12m 정도이며, 체중은 약 20톤 정도입니다. 등은 흑색이며 옆과 배 뒤쪽은 회흑색입니다. 주둥이 위로 3개의 융기선이 있으며, 몸 전체 특히 등 쪽에 타원형의 상처 같은 모양 있어요. 목주름은 배꼽까지 연장되어 있으며, 등지느러미는 높이가 약 50cm 정도입니다.\n\n임신 기간은 12개월이며, 2~3년에 한번 출산하고, 수명은 최대 약 60년 정도입니다. 먹이로는 멸치, 정어리 등 떼 지어 다니는 소형 어류와 요각류 등을 먹으며 보통 1~2마리가 무리를 이루어 회유하는 것으로 알려져 있습니다.','바다'),(46,'장수삿갓조개',1,100,'/static/images/sticker_장수삿갓조개.png','껍질의 높이 1cm, 긴 부분 4cm, 짧은 부분 3cm 정도이며, 낮은 삿갓형으로 황백색입니다. 껍질의 안쪽은 흰색이고 광택을 띠지는 않습니다.\n\n조간대부터 수심 10m 정도의 노출된 암반지역에 서식합니다.','바닷속암반'),(47,'해송',1,100,'/static/images/sticker_해송.png','몸통은 소나무 모양이며,붉은 갈색을 띠며 크기는 높이 2m까지 자란답니다.\n\n수심 20~100m 범위의 암반에 부착하여 서식하며,가지에는 줄새우류, 게류 등 다양한 무척추동물이 공생하므로 생태적으로 중요한 위치를 차지합니다.','바닷속암반'),(48,'북방긴수염고래',1,100,'/static/images/sticker_북방긴수염고래.png','몸 길이는 출생 시 약 4.5m, 다 자랐을 때 15m 정도이며, 체중은 80~100톤 정도입니다. 암컷이 수컷보다 크며, 전체가 흑색이고, 복부에 형태가 일정하지 않은 백색 반점이 있습니다. 머리 부가 몸 전체의 1/4로 매우 크며, 턱 선이 크게 아치형으로 굽어져 있습니다. 머리에는 경결(티눈)이 곳곳에 산재해 있으며, 아래턱과 배에는 주름이 없습니다. 가슴지느러미는 넓고 끝이 부채처럼 넓적하며, 등지느러미는 없습니다. 피하지방층의 두께는 최대 40cm 정도입니다.\n\n임신기간은 10~12개월이며, 겨울과 봄에 따뜻한 해역에서 3~4년에 한번 출산합니다. 고래수염을 이용하여 동물플랑크톤(주로 칼라누스 등의 요각류) 및 기타 소형 갑각류를 먹이로 취합니다. 주로 1~2마리가 무리 지어 헤엄치지만, 번식장이나 섭이장(먹이 활동장)에서는 큰 무리를 짓기도 하며, 주로 깊이 잠수를 하기 전에 꼬리지느러미를 물 밖으로 올린다. 짝짓기 시즌에는 수컷들이 서로 경쟁을 하며 암컷을 유혹합니다.','바다'),(49,'남방큰돌고래',2,100,'/static/images/sticker_남방큰돌고래.png','다 큰 남방큰돌고래는 최대 2.7m, 체중 230kg정도로 중형 돌고래이며, 유선형의 체형을 가집니다. 짙은 회색의 등 표면은 꼬리 쪽으로 갈수록 옅어지며, 복부의 색은 밝은 회색에서 백색입니다. 머리는 둥굴며, 주둥이는 도드라지게 튀어나와 있습니다.\n\n인간에 대한 친화력이 뛰어난 종이지만, 연안 생태계의 최상위 포식자랍니다. 우리나라 제주 연안에서 정착해 살며, 총 114마리가 산답니다. 제주 연안에서 서식하는 개체군은 전 세계에 분포하는 남방큰돌고래 개체군 중 개체 수가 가장 적어요.','바다'),(50,'망둥어',1,100,'/static/images/sticker_망둥어.png','몸길이는 10~20cm 정도입니다. 배지느러미는 맞붙어 흠반을 이루고, 등지느러미는 2개입니다.\n\n물 온도와 염분 변화를 잘 견딥니다.','갯벌'),(51,'망상맵시산호',1,100,'/static/images/sticker_망상맵시산호.png','몸통은 부채모양이며 선명한 붉은색을 띱니다. 몸통의 높이는 약 20cm정도이고, 폭은 이보다 조금 더 넓습니다.\n\n제주도 서귀포 문섬, 범섬에 서식합니다.','바닷속암반'),(52,'큰바다사자',1,100,'/static/images/sticker_큰바다사자.png','수컷의 평균 몸 길이는 3.3m, 평균 체중은 1,000 kg, 암컷의 평균 몸 길이는 2.5m, 평균 체중은 273 kg입니다. 체격이 거대하고 강하게 보이며, 바다사자보다 체격이 큽니다. 성숙한 수컷은 두개골 정수리에 볏 모양의 돌출이 있으나 암컷과 미성숙 개체는 분명하지 않습니다. 번식기의 수컷은 목과 어깨 부근에 길고 거친 갈기털이 늘어져있습니다. 앞뒤 지느러미는 매우 길고 넓습니다. 성숙한 개체의 체색은 등 쪽으로는 담황 혹은 황갈색이나 배 쪽으로 갈수록 갈색으로 어두워집니다. 대부분의 기각류와는 달리, 젖었을 때의 색깔은 더욱 엷어져 회백색으로 보입니다.\n\n번식 장소 주변의 해양에서 1년 내내 무리를 지어 생활하며, 최대 30년 정도 생존합니다. 일부다처제로 한마리의 수컷과 10여 마리의 암컷이 번식 집단을 구성하여 늦은 봄부터 여름까지 한대 해역의 외딴 섬에서 새끼를 낳습니다. 때때로 어획 기구 주변에 몰려서 어획된 어류를 섭취하기도 합니다. 어류, 오징어류, 조개류,게류 및 다른 물개류의 새끼 등 다양한 먹이를 섭식합니다.','연안'),(53,'미립이분지돌산호',1,100,'/static/images/sticker_미립이분지돌산호.png','몸통은 나무모양을 하며 주황색을 띱니다. 촉수는 반투명으로 노란 점들이 흩어져있습니다. 몸통의 크기는 다양한데 가장 큰 개체의 높이는 15cm 정도랍니다.\n\n수심 15~30m의 암반에 부착하여 서식하며, 태형동물, 석괴관갯지렁이, 따개비, 히드라 등이 붙어삽니다. 성장이 매우 느린 것으로 알려져 있습니다.','바닷속암반'),(54,'청다리도요사촌',1,100,'/static/images/sticker_청다리도요사촌.png','몸길이는 약 29~32cm이며 몸길이에 비해 다리가 짧은 것이 특징입니다. 크고 굵은 부리는 길고 위로 휘어지며, 노란색을 조금 띱니다. 다리는 길고 노란색입니다. 암컷과 수컷 모두 여름에는 머리와 가슴에 검은색의 반점이 뚜렷하고, 몸의 윗면은 검게 보입니다. 겨울에는 머리와 목에 줄무늬가 약하게 있으며, 몸의 윗면은 흐린 회색입니다. 날 때 꼬리 뒤로 다리가 약간 나와 있으며, 알은 검은 갈색 반점이 있는 청록색입니다.\n\n적은 수의 청다리도요사촌이 국내에 방문하며, 뚜렷한 개체군 감소로 멸종 가능성이 높은 국제적 보호종입니다. 이들에게는 먹이를 제공해주는 넓은 갯벌이 매우 필요합니다.','갯벌'),(55,'금빛나팔돌산호',1,100,'/static/images/sticker_금빛나팔돌산호.png','몸통은 촉수를 펼쳤을 때 말미잘 모양과 비슷합니다.가지는 보통 밝은 살구색을 띠며 촉수는 반투명한 노란색이고 입부분은 선명한 붉은색을 띱니다.\n\n수심 15~30m 범위에서 주로 서식하는 것으로 알려져있습니다. 태형동물,히드라,갯지렁이 등이 흔히 붙어서 살며,성장과 확산속도가 매우 느리답니다.','바닷속암반'),(56,'두이빨사각게',1,100,'/static/images/sticker_두이빨사각게.png','분류학적으로 십각목 바위게과에 속하며 다 자라면 너비 약 35mm, 길이 약 33mm 정도까지 자라는 중형 종입니다. 등갑은 정사각형에 가까우며 앞보다 뒤가 조금 넓은 모양입니다. 특히 눈 뒤 가시가 두 개인 점이 이 종의 특징인데 앞의 것은 뚜렷하고 뒤의 것은 뚜렷하지 않습니다. 집게발은 좌우대칭이며 수컷이 암컷에 비해서 훨씬 크고 억세게 생겼다.\n\n제주도 해안 남쪽의 바닷물과 민물이 만나는 하구역(강정천 등)에 서식하며, 제한된 곳에 서식하는 만큼 연안개발에 취약하다. 잡식성으로 물고기 등 동물의 사체나 음식물 찌꺼기 등을 먹는데 특히 나방이나 야행성 곤충 등이 물에 떨어지면 잘 잡아먹이로 삼습니다. 서식면적이 좁고, 개체 수가 많지 않으며 향후 개체군이 늘어날 가능성 또한 높지 않습니다.','하구역'),(57,'흰수염바다오리',1,100,'/static/images/sticker_흰수염바다오리.png','기러기목 오리과의 여름철새로 몸의 각 부위 길이는 날개 172~182mm, 꽁지 45~62mm, 발목 28~32mm, 부리 32~39mm입니다. 몸 색은 암수가 같은 빛깔입니다. 등 쪽은 검은 갈색이며, 배 쪽은 흰색에 약간의 어두운 회색의 무늬가 있습니다. 옆얼굴에는 두 줄의 흰 깃이 있습니다. 턱 밑과 목, 윗가슴 및 겨드랑이는 갈색을 띤 어두운 회색입니다. 겨울에는 가슴과 배가 흰색이며 무늬가 없습니다. 알은 광택이 없는 회백색 바탕에 연한 갈색이나 어두운 회색의 줄무늬와 점이 약간 흩어져 있습니다.\n\n한류를 따라 회유하는 어류에 의존하는 조류로서, 어구에 의해 함께 잡히는 피해가 발생할 수 있습니다. * 전 세계 개체군은 1,300,000개체 이상으로 추정','연안'),(58,'고래상어',1,100,'/static/images/sticker_고래상어.png','어류 가운데 가장 큰 물고기로, 다 자란 고래상어의 경우, 몸길이가 18m에 이르는 것으로 알려져 있습니다. 다른 상어류와 달리 입이 주둥이 끝부분에 있습니다. 턱에는 약 300열의 매우 작은 이빨이 있답니다.\n\n아가미에는 스펀지와 같은 조직이 있어 물과 함께 입을 들어온 먹이를 여과하여 먹는답니다. 주로 플랑크톤, 작은 갑각류, 떼 지어 다니는 물고기를 먹고 및 작은 참치나 오징어도 먹습니다.','바다'),(59,'참고래',1,100,'/static/images/sticker_참고래.png','몸길이는 출생 시 약 6m 정도이며, 다 자랐을 때는 약 23m, 체중은 약 75톤 정도입니다. 대왕고래 다음으로 큰 고래이며, 등과 옆면은 짙은 회색 혹은 암갈색이에요. 꼬리와 가슴지느러미를 포함한 배 쪽은 흰색입니다. 머리 오른쪽의 아래턱과 고래수염이 흰 색인 반면, 왼쪽은 검은색으로 비대칭을 이루는 것이 가장 큰 특징입니다. 등지느러미에서 꼬리지느러미 사이에 명확한 융기선이 있어요. 등지느러미는 높이 60cm 이상이며, 가슴지느러미는 비교적 짧고 좁습니다. 아래턱부터 배꼽까지 56~100개의 주름이 있어요.\n\n임신 기간은 11~12개월로, 2~3년에 한번 출산하며, 수명은 약 100년 이상입니다. 다른 수염고래류에 비해 군성(무리를 짓는 습성)이 강하여 2~7마리가 무리를 이루며, 유영 속도가 빠른 편입니다. 먹이로는 소형 갑각류인 난바다곤쟁이, 요각류인 칼라누스류 혹은 두족류인 오징어 등을 먹습니다.','바다'),(60,'잔가지나무돌산호',1,100,'/static/images/sticker_잔가지나무돌산호.png','몸통은 나뭇가지 모양으로 굵고 원통형의 가지를 가지며,가지 길이는 약 3~7cm 정도입니다. 몸색깔은 진하고 선명한 노란색 또는 주황색이며 촉수는 이보다 약간 연한 편입니다.','바닷속암반'),(61,'흰수지맨드라미',1,100,'/static/images/sticker_흰수지맨드라미.png','몸통은 나무모양을 하며, 흰색입니다. 크기는 약 30~50cm 정도이고 폭은 같거나 다소 좁습니다.\n\n수심 15~30m 범위의 물 흐름이 원활한 암반에 부착하여 서식하며, 개체수가 매우 적은 희귀종입니다.','바닷속암반'),(62,'점해마',1,100,'/static/images/sticker_점해마.png','몸길이는 약 18cm 정도로, 연한 노란색, 연합 녹색, 연합 빨간색 등 다양한 몸색깔을 가집니다. 아가미 뒤부터 등지느러미까지 등쪽부분에 갈색, 검정색 반점이 있습니다.\n\n예전에 비해 많이 발견되지 않으며, 발견된 점해마의 대부분이 암컷으로 수컷을 발견하기 힘듭니다.','바다숲'),(63,'푸른바다거북',2,100,'/static/images/sticker_푸른바다거북.png','비교적 머리가 작고 등갑이 단단하며 심장모양입니다. 몸색깔은 황록색에서 검은색으로 다양합니다. 새끼의 몸색깔은 암청색부터 검은색까지 다양합닏나. 다 자란 때의 등껍질의 길이는 70~153cm 범위이며 몸무게는 평균 110~190kg 정도로 비교적 큰 바다거북에 속한답니다. 다른 바다거북에 비해 비교적 몸이 납작한 편입니다.\n\n전 세계 개체추는 한 때 수백만 마리였으나 최근에는 산란에 참여하는 암컷이 약 20만마리 정도로 추정됩니다.','바다'),(64,'피뿔고둥',1,100,'/static/images/sticker_피뿔고둥.png','길이는 약 11cm, 너비는 약 8cm 정도로, 주걱 모양의 껍질을 가지고 있습니다. 매우 두껍고 단단하며 무겁습니다.\n\n수심 10m의 모래나 펄이 섞여 있는 바위에 서식합니다.','갯벌'),(65,'거머리말',1,100,'/static/images/sticker_거머리말.png','키가 30~210cm, 잎의 폭은 1cm, 잎맥수는 5~11개로 나타나며, 꽃이 피는 가지는 50~350cm의 키를 가집니다. 땅속을 기는 0.5cm 지름의 땅속즐기가 성장하고, 땅속 즐기의 마디 길이는 1~4cm이며, 마디마다 다수의 뿌리가 자란답니다.\n\n조간대부터 수심 5m 미만의 물살이 느린 환경에서 비교적 큰 무리를 이루며 서식합니다. 암수한몸의 다년생 여러해살이풀로 서식 환경과 계절에 따라 포기 수, 무게, 성장 속도 등이 변화합니다. 겨울에 암꽃과 수꽃이 같이 피는 꽃가지가 발생하고 수정이 이루어져 여름에 씨가 성숙합니다.','바다숲'),(66,'별혹산호',1,100,'/static/images/sticker_별혹산호.png','몸통은 부채모양으로, 선홍색이며, 촉수는 작고 흰색을 띱니다. 몸통의 높이는 최대 50cm까지 자라기도 하며, 폭은 이보다 좁습니다.\n\n수심 20~50m 암반에 부착하여 서식하며, 이들은 집단을 이루지 않고 독립적으로 발견되는데, 때때로 여러 개체가 모여있기도 합니다. 최근 10년 동안 지속적으로 발견되고 있는 대표적인 난류성 종이랍니다.','바닷속암반'),(67,'둔한진총산호',1,100,'/static/images/sticker_둔한진총산호.png','몸통은 부채모양이며, 노란색이나 연한 주황색을 띱니다. 몸통의 높이는 약 20cm 정도이고, 폭은 이보다 다소 좁습니다.\n\n해류의 흐름이 원활한 수심 15~40m 사이에 서식하며, 성장속도가 느린 것으로 알려져 있습니다.','바닷속암반'),(68,'착생깃산호',1,100,'/static/images/sticker_착생깃산호.png','몸통은 새의 깃털과 유사하며 살구색 또는 연미색을 띠고, 높이는 15~25cm 정도입니다.\n\n수심 25~100m 범위에 서식하는 것으로 알려져 있으며,해류의 소통이 원활한 암밤에 부착하여 생활합니다.','바닷속암반'),(69,'점박이물범',2,100,'/static/images/sticker_점박이물범.png','수컷의 평균 크기는 1.7m 정도이고 체증은 약 120 kg이며, 암컷은 평균적으로 크기 1.6m, 체중은 80 kg 정도입니다. 몸 색깔은 일반적으로 엷은 은회색이나, 변이가 많으며 불규칙한 무늬의 점들이 흩어져 있습니다. 태어날 때에는 긴 양모 같은 흰 배내털을 가지고 있으나 태어나고 2~4주 정도 지나면 털갈이를 합니다.\n\n1년에 한번 주로 1월부터 4월 중반 얼음 위에서 변식을 합니다. 수명은 32년 정도이며, 한 수컷이 한 마리의 암컷과 번식하며 자기 영역을 가집니다. 주로 물고기와 오징어 따위를 잡아먹으며 최대 수심 30m 정도 잠수하기도 합니다.','바다숲'),(70,'넓적부리도요',1,100,'/static/images/sticker_넓적부리도요.png','검은색의 스푼처럼 생긴 부리와 다리를 가졌으며, 여름 깃과 겨울 것이 다르다. 여름에는 이마에서 뒷목까지 붉은 갈색이며, 목 가장자리 끝과 허리 양쪽은 흰색입니다. 머리 옆, 얼굴, 귀깃, 앞 목, 목 옆, 가슴은 붉은 갈색으로 검은색의 작은 얼룩무늬가 있습니다. 배와 아래 꼬리 덮깃은 흰색입니다. 겨울에는 이마와 눈앞이 흰색이며, 눈 위에는 흰색의 얼룩무늬가 있습니다. 턱밑과 턱 아래 부위는 흰색이고, 목 옆에는 어두운 갈색의 작은 얼룩무늬가 있습니다. 몸 면은 잿빛 갈색으로 가장자리가 흰색이고, 검은 갈색의 축이 되는 반점이 있습니다.\n\n해만, 해안의 간척지, 해안의 얕은 물가, 소택지, 하구, 염전 등에 방문합니다. 건조한 갯벌에서는 부리를 좌우로 찔러 넣으며 먹이를 찾고, 얕은 물에서는 천천히 걸으며 부리를 약간 벌리고 빠르게 좌우로 저으면서 먹이를 찾습니다. 과거 중부 이남에서 흔한 겨울새였으나, 전 세계적으로 개체 수가 크게 감소하였으며, 특히 새만금 사업 이후 국내 도래 개체 수가 급격하게 감소하였습니다. 현재 국제적인 복원 프로그램이 진행되고 있습니다. * 전 세계적으로 약 450~1,000개체 정도 생존 추정','연안'),(71,'장수거북',1,100,'/static/images/sticker_장수거북.png','가장 큰 바다거북으로 평균 등딱지 길이가 140~180cm이며, 가장 큰 것은 길이 3m, 무게 900kg 입니다. 등껍질에는 5~7개의 세로 줄이 있답니다. 위턱의 앞 가장자리에 2개의 날카로운 부분이 있으며, 가죽성 피부로 덮혀진 등껍질을 가집니다. 다른 바다거북에게서 볼 수 있는 비늘판은 없는 것으로 다른 종과 구별됩니다. 몸색깔은 매우 검고 피부상에 약간의 희거나 분홍색의 반점이 있으며 선단부에는 앞 지느러미 발은 매우 크며, 뒤 지느러미 발은 피부 주름에 의해 꼬리와 연결되어 있으며 발톱은 없답니다.\n\n높은 지방함량, 대형의 몸체, 역류(counter-current) 열 교환 시스템 등으로 인해 내부의 온도가 외부 온도보다 높아 찬물에서도 잘 견딜 수 있답니다. 최근에 태평양의 개체 수가 80% 이상 감소한 것으로 국제 자연보전연맹(IUCN)이 추정한 바 있는데 다른 해역에서는 이렇게 심각하지는 않습니다.','바다'),(72,'노랑부리백로',1,100,'/static/images/sticker_노랑부리백로.png','몸길이는 65~68cm입니다. 여름에는 몸은 흰색이고, 부리와 발가락은 노란색이며, 다리는 검은색입니다. 눈 앞부분이 푸른색을 띠며, 뒷머리의 댕기 깃털과 가슴과 등의 장식깃털이 자라납니다. 겨울에는 댕기 깃털과 장식깃털이 없어지고 부리는 흑갈색, 다리는 녹황색 또는 갈색입니다.\n\n4월부터 방문하기 시작하여 10월까지 서식합니다. 무리를 이루어 집단 번식을 하며 마른 나뭇가지를 모아 접시 모양의 둥지를 만들고 청록색의 알을 3~4개 정도 낳습니다. 먹이는 해안가의 갯벌, 하구, 논에서 어류나 갑각류 등을 잡아 먹이로 삼습니다. 번식을 마치고 내려오는 시기에는 연안의 갯벌에서 일부 무리들이 종종 관찰됩니다.','갯벌'),(73,'남방방게',1,100,'/static/images/sticker_남방방게.png','등껍질은 사각형이며, 가로 길이가 세로 길이보다 넓습니다. 눈구멍 뒤에 4개의 이빨 모양의 돌기가 있습니다. 등껍질에는 작은 과립들과 짧은 털이 촘촘하게 나있습니다. 손바닥의 양면이 볼록하고, 눈 아래 두둑 위에는 작은 과립이 16~17개 촘촘히 배열되어 있습니다.\n\n암석이 많은 모래펄 지역에 구멍을 파고 살고 있습니다.','갯벌'),(74,'가시해마',2,100,'/static/images/sticker_가시해마.png','우리나라에 서식하는 해마 중 가장 두드러진 가시를 가지며, 가시의 끝은 갈라져 있습니다. 주둥이는 비교적 길며, 띠를 가집니다.','바다숲'),(75,'대추귀고둥',1,100,'/static/images/sticker_대추귀고둥.png','세로 길이 3.5cm, 가로 길이 1.7cm 정도의 껍질을 가지며, 긴 달걀모양으로 전체적으로 대추 모양을 하고 있습니다. 밀물 때 바닷물과 맞닿는 갯벌의 윗 부분 중에서도 갯 잔디가 있는 지역에 서식합니다.','하구역'),(76,'낡은 장화',0,0,'/static/images/trash_boot.png','누군가 버린 장화입니다.','쓰레기'),(77,'폐타이어',0,0,'/static/images/trash_tire.png','바다에 버려진 낡은 타이어입니다. 환경오염의 주범입니다.','쓰레기'),(78,'플라스틱 병',0,0,'/static/images/trash_bottle.png','분해되는 데 수백 년이 걸리는 플라스틱 병입니다.','쓰레기'),(79,'찌그러진 캔',0,0,'/static/images/trash_can.png','누군가 마시고 버린 빈 캔입니다.','쓰레기');
